{"code": "export async function main(input: unknown) {
  const { issues } = await sdk.sentry.listIssues({ project: "web" });
  const candidates = issues.filter(i => i.status === "unresolved" && i.count >= 50);
  const checked = issues.length;
  const created: any[] = [];
  const toCreate: { title: string; culprit: string; file: string; line: number }[] = [];
  for (const issue of candidates) {
    const existing = (await sdk.linear.searchIssues({ query: issue.culprit })).issues;
    const fileExisting = (await sdk.linear.searchIssues({ query: issue.filename })).issues;
    const mentioned = existing.length + fileExisting.length > 0;
    if (mentioned) continue;
    toCreate.push({ title: issue.title, culprit: issue.culprit, file: issue.filename, line: issue.lineNumber });
  }
  for (const t of toCreate) {
    const blame = await sdk.github.getBlame({ file: t.file, line: t.line });
    const issue = await sdk.linear.createIssue({
      title: `[Sentry] ${t.title}`,
      description: t.culprit,
      assigneeEmail: blame.authorEmail,
    });
    created.push({ planned: { title: `[Sentry] ${t.title}`, description: t.culprit, assigneeEmail: blame.authorEmail }, issue });
  }
  return { checked, created };
}"}

